// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {airdrop} from "../src/airdrop.sol";

contract Reverter {
    fallback() external payable { revert(); }
}

contract InvMutTest is Test {
    airdrop c;
    function setUp() public { c = new airdrop(); }

    function testFuzz_property(address from, uint256 v) public {
        Reverter rev = new Reverter();
        address[] memory tos = new address[](1);
        tos[0] = address(rev);

        bool ok;
        try c.transfer(from, address(rev), tos, v) returns (bool r) {
            ok = r;
        } catch {
            ok = false;
        }

        // P: the external call to the reverting callee always fails, so the require(_s) always reverts;
        //    hence the reference transfer never returns true here.
        // M: the require(_s) was replaced by a no-op, so the function reaches `return true` and returns true.
        assertTrue(!ok);
    }
}
